def emit(kind,value):print('CATEGORY_REFS_V2_'+kind+' '+json.dumps(value,ensure_ascii=False),flush=True)
def run():
    try:
        lr=_api_login('v3')
        if lr is None or not lr.ok:raise RuntimeError('PHH auth unavailable')
        token=lr.json()['token'];summary,arts=export_all('v3',100,persist=False,token=token)
        cats=json.loads(arts['pmp-categories-full.json'])['category_list'];by={c['category_id']:c for c in cats}
        for c in cats:
            if not c.get('allow_add_products'):continue
            emit('TAXONOMY',dict(id=c['category_id'],en=c.get('title_en'),lv=c.get('title_lv'),lt=c.get('title_lt'),ru=c.get('title_ru'),path=_category_path(c['category_id'],by),required=[{k:a.get(k) for k in ('field_id','title_lt','title_lv','title_ru')} for a in c.get('attributes',[]) if a.get('required')]))
        unique=list(dict.fromkeys(r['lookup_ean'] for r in REFS if r['lookup_ean']))
        def one(ean):
            time.sleep(.15)
            for attempt in range(3):
                r=_api_get('/v3/products/product-modifications/barcodes?ean='+ean,token)
                if r.status_code!=429:break
                time.sleep(10*(attempt+1))
            try:b=r.json()
            except Exception:b={}
            matches=[x for x in b if (x.get('modification') or {}).get('app_name')=='220.lv'] if isinstance(b,list) else []
            return ean,{'http':r.status_code,'matches':[{'pigu_external_id':x.get('id'),'category_id':((x.get('modification') or {}).get('category') or {}).get('id')} for x in matches]}
        checked={};bycategory={};errors=0
        with concurrent.futures.ThreadPoolExecutor(max_workers=4) as pool:
            futs={pool.submit(one,ean):ean for ean in unique}
            for f in concurrent.futures.as_completed(futs):
                try:ean,result=f.result();checked[ean]=result
                except Exception as e:checked[futs[f]]={'http':None,'error':type(e).__name__+': '+str(e),'matches':[]}
                if len(checked)%100==0:emit('PROGRESS',{'checked':len(checked),'total':len(unique)})
        for ref in REFS:
            result=checked.get(ref['lookup_ean'],{'http':None,'matches':[]})
            for match in result['matches']:
                cid=str(match['category_id'])
                out=dict(ref,**match,http=result['http'])
                bycategory.setdefault(cid,[]).append(out)
        for cid,rs in sorted(bycategory.items(),key=lambda x:int(x[0]) if x[0].isdigit() else 0):
            # Every successful source row is retained, small log records avoid truncation.
            for r in rs:emit('REFERENCE',r)
        emit('DONE',{'taxonomy_categories':len(cats),'addable':summary['leaf_addable_categories'],'sia_rows':len(REFS),'unique_gtins':len(unique),'checked':len(checked),'matched_rows':sum(len(v) for v in bycategory.values()),'http_counts':{str(x):sum(v.get('http')==x for v in checked.values()) for x in {v.get('http') for v in checked.values()}},'phh_writes':0})
    except Exception as e:emit('ERROR',{'error':type(e).__name__+': '+str(e)})
